def summarize(tr):
    d = frame_diff(tr.before_frame, tr.after_frame)
    out = {'n': d['changed_cell_count']}
    for k,v in d.items():
        if k=='changed_cell_count': continue
        out[k] = [(e.get('at'), e.get('color'), e.get('pixels'), e.get('before_color'), e.get('after_color'), e.get('bbox')) for e in v][:8]
    return out
